 "content": "def transform(grid):
    """Fill cells lying strictly between same-colored markers in a row or column."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    marker = [[grid[r][c] != bg for c in range(w)] for r in range(h)]
    for r in range(h):
        cols = [c for c in range(w) if marker[r][c]]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if marker[r][c]]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
